-- #1730 - why an order was cancelled, as data. Every CANCELLED status event from now on carries the
-- path that released it (shopper changed the order at checkout, payment link expired, payment
-- failed, checkout abandoned before a payment session, payment provider unavailable, or a staff
-- cancellation). The storefront and staff panel use it for labels; whether an order was ever PAID is
-- read from "Payment", not from here.
--
-- HAND-AUTHORED, not generated by `prisma migrate dev --create-only`: that command refuses on the
-- dev database ("The migration `20260820200500_p8_image_needs_review` was modified after it was
-- applied") and offers only `migrate reset`, which would delete every row - the open `#895`. The DDL
-- below is Prisma's own output, unedited, from `prisma migrate diff --from-schema-datamodel
-- <staging schema> --to-schema-datamodel prisma/schema.prisma --script`, so it touches no database
-- and cannot propose removing the hand-authored `pg_trgm` indexes (`#508`).
--
-- Additive: one enum and one nullable column. The backfill below NEVER GUESSES: a historical event
-- gets an origin only when its note is exactly the string the releasing code path writes, or when
-- it carries a #1691 staff cancellation reason. Every other CANCELLED event stays NULL ("reason not
-- recorded").

-- CreateEnum
CREATE TYPE "CancellationOrigin" AS ENUM ('CHECKOUT_CHANGED', 'CHECKOUT_ABANDONED', 'PAYMENT_EXPIRED', 'PAYMENT_FAILED', 'PROVIDER_UNAVAILABLE', 'STAFF');

-- AlterTable
ALTER TABLE "OrderStatusEvent" ADD COLUMN     "cancellationOrigin" "CancellationOrigin";

-- Backfill (exact notes only)
UPDATE "OrderStatusEvent" SET "cancellationOrigin" = 'CHECKOUT_CHANGED'
  WHERE "status" = 'CANCELLED' AND "note" = 'Shopper cancelled payment at checkout';

UPDATE "OrderStatusEvent" SET "cancellationOrigin" = 'PAYMENT_EXPIRED'
  WHERE "status" = 'CANCELLED' AND "note" IN (
    'Checkout session expired; stock released.',
    'Checkout session expired; released by the scheduled payment sweep.'
  );

UPDATE "OrderStatusEvent" SET "cancellationOrigin" = 'PAYMENT_FAILED'
  WHERE "status" = 'CANCELLED' AND "note" IN (
    'Payment failed; stock released.',
    'Payment never settled; released by the scheduled payment sweep.'
  );

UPDATE "OrderStatusEvent" SET "cancellationOrigin" = 'CHECKOUT_ABANDONED'
  WHERE "status" = 'CANCELLED'
    AND "note" = 'No payment session was ever created; released by the scheduled payment sweep.';

UPDATE "OrderStatusEvent" SET "cancellationOrigin" = 'PROVIDER_UNAVAILABLE'
  WHERE "status" = 'CANCELLED'
    AND "note" = 'Payment provider unavailable; order cancelled and stock released.';

UPDATE "OrderStatusEvent" SET "cancellationOrigin" = 'STAFF'
  WHERE "status" = 'CANCELLED' AND "cancellationReason" IS NOT NULL;
